class ServiceTicketDetail(AgencyZoomModel):
    """Service Ticket object"""

    id: OptInt = None
    """The id of service ticket"""
    agency_id: OptInt = Field(default=None, alias="agencyId")
    """The id of agency"""
    household_id: OptInt = Field(default=None, alias="householdId")
    """The id of household"""
    workflow_id: OptInt = Field(default=None, alias="workflowId")
    """The id of pipeline"""
    workflow_stage_id: OptInt = Field(default=None, alias="workflowStageId")
    """The id of pipeline stage"""
    status: OptInt = None
    """The status of service ticket Example: ``0=remove; 2=completed; 1=active;``."""
    status_desc: Optional[str] = Field(default=None, alias="statusDesc")
    """The status description of service ticket Example: ``Open, Deleted, Completed``."""
    csr: OptInt = None
    """The id of CSR"""
    enter_stage_ts: Optional[str] = Field(default=None, alias="enterStageTS")
    """The timestamp when enter a stage. In practice: returned as a datetime string, "YYYY-MM-DD HH:MM:SS"."""
    enrolled: OptInt = None
    """Whether enroll automation"""
    create_date: Optional[str] = Field(default=None, alias="createDate")
    """The create date of this ticket Example: ``2021-08-01``."""
    created_by: Optional[str] = Field(default=None, alias="createdBy")
    """The id of agent. In practice: returned as the user's display name."""
    modify_date: Optional[str] = Field(default=None, alias="modifyDate")
    """Modify date of this ticket Example: ``2021-08-01 23:23:23``."""
    modified_by: Optional[str] = Field(default=None, alias="modifiedBy")
    """The id of agent. In practice: returned as the user's display name."""
    category_id: OptInt = Field(default=None, alias="categoryId")
    """Service ticket category Example: ``0 = all;``."""
    priority_id: OptInt = Field(default=None, alias="priorityId")
    """Service ticket priority Example: ``0 is all``."""
    subject: Optional[str] = None
    """The subject of this ticket"""
    service_desc: Optional[str] = Field(default=None, alias="serviceDesc")
    """The description of this ticket"""
    due_date: Optional[str] = Field(default=None, alias="dueDate")
    """Due date. In practice: returned as a date string, "YYYY-MM-DD"."""
    complete_date: Optional[str] = Field(default=None, alias="completeDate")
    """Complete date"""
    resolution_id: OptInt = Field(default=None, alias="resolutionId")
    """Resolution Id"""
    resolution_desc: Optional[str] = Field(default=None, alias="resolutionDesc")
    """Resolution description"""
    last_activity_date: Optional[str] = Field(default=None, alias="lastActivityDate")
    """Last Activity date Example: ``2019-01-01 01:01:01``."""
    vendor: Optional[str] = None
    """Vendor Name"""
    source: Optional[str] = None
    """Source"""
    response_minutes: OptInt = Field(default=None, alias="responseMinutes")
    """Response minutes Example: ``1``."""
    email_thread_id: OptInt = Field(default=None, alias="emailThreadId")
    """Email thread's id"""
    name: Optional[str] = None
    """Household name"""
    workflow_name: Optional[str] = Field(default=None, alias="workflowName")
    """The pipeline name"""
    workflow_stage_name: Optional[str] = Field(default=None, alias="workflowStageName")
    """Name of pipeline stage"""
    phone: Optional[str] = None
    """Phone of household"""
    email: Optional[str] = None
    """Email of household"""
    csr_firstname: Optional[str] = Field(default=None, alias="csrFirstname")
    """CSR firstname"""
    csr_lastname: Optional[str] = Field(default=None, alias="csrLastname")
    """CSR lastname"""
    category_name: Optional[str] = Field(default=None, alias="categoryName")
    """Service ticket category name"""
    priority_name: Optional[str] = Field(default=None, alias="priorityName")
    """Service ticket priority name"""
    household_firstname: Optional[str] = Field(default=None, alias="householdFirstname")
    """Household firstname"""
    household_middlename: Optional[str] = Field(default=None, alias="householdMiddlename")
    """Household middlename"""
    household_lastname: Optional[str] = Field(default=None, alias="householdLastname")
    """Household lastname"""
    other_producers: Optional[List[ServiceTicketDetailOtherProducersItem]] = Field(
        default=None, alias="otherProducers"
    )
    """Other producers information"""
    custom_fields: Optional[List[CustomField]] = Field(default=None, alias="customFields")
    """A list of custom fields"""


